import { test } from 'node:test';
import assert from 'node:assert/strict';
import express from 'express';
import {
  badRequest,
  unauthorized,
  forbidden,
  notFound,
  conflict,
  notFoundHandler,
  errorHandler,
} from '../dist/shared/errors.js';

test('error factories and middleware produce correct responses', async () => {
  const app = express();

  app.get('/bad', (_req, _res, next) => next(badRequest('bad input', { field: 'x' })));
  app.get('/unauth', (_req, _res, next) => next(unauthorized()));
  app.get('/forbidden', (_req, _res, next) => next(forbidden()));
  app.get('/notfound', (_req, _res, next) => next(notFound('Widget')));
  app.get('/conflict', (_req, _res, next) => next(conflict('already exists')));
  app.get('/boom', (_req, _res, next) => next(new Error('kaboom')));

  app.use(notFoundHandler);
  app.use(errorHandler);

  const server = app.listen(0);
  await new Promise((resolve) => server.once('listening', resolve));
  const port = server.address().port;
  const base = `http://localhost:${port}`;

  try {
    const bad = await fetch(`${base}/bad`);
    assert.equal(bad.status, 400);
    const badBody = await bad.json();
    assert.equal(badBody.error, 'bad input');
    assert.deepEqual(badBody.details, { field: 'x' });

    const unauth = await fetch(`${base}/unauth`);
    assert.equal(unauth.status, 401);
    assert.equal((await unauth.json()).error, 'Authentication required');

    const forb = await fetch(`${base}/forbidden`);
    assert.equal(forb.status, 403);
    assert.equal((await forb.json()).error, 'Not allowed');

    const nf = await fetch(`${base}/notfound`);
    assert.equal(nf.status, 404);
    assert.equal((await nf.json()).error, 'Widget not found');

    const conf = await fetch(`${base}/conflict`);
    assert.equal(conf.status, 409);
    assert.equal((await conf.json()).error, 'already exists');

    const boom = await fetch(`${base}/boom`);
    assert.equal(boom.status, 500);
    assert.equal((await boom.json()).error, 'Internal server error');

    const unrouted = await fetch(`${base}/does-not-exist`);
    assert.equal(unrouted.status, 404);
    assert.equal((await unrouted.json()).error, 'Route not found');
  } finally {
    await new Promise((resolve) => server.close(resolve));
  }
});

