test('sequentialIds generates deterministic prefixed ids', () => {
  const gen = sequentialIds('user');
  assert.equal(gen(), 'user-1');
  assert.equal(gen(), 'user-2');
  assert.equal(gen(), 'user-3');
});

test('paginate slices items and returns metadata', () => {
  const items = Array.from({ length: 25 }, (_, i) => i);
  const parsed = paginationSchema.parse({ page: '2', pageSize: '10' });
  const result = paginate(items, parsed);
  assert.deepEqual(result.items, items.slice(10, 20));
  assert.equal(result.page, 2);
  assert.equal(result.pageSize, 10);
  assert.equal(result.total, 25);
  assert.equal(result.totalPages, 3);
});

test('paginate defaults page/pageSize and handles empty input', () => {
