  assert.equal(parsed.page, 1);
  assert.equal(parsed.pageSize, 20);
  const result = paginate([], parsed);
  assert.deepEqual(result.items, []);
  assert.equal(result.total, 0);
  assert.equal(result.totalPages, 1);
});

