test('requestLogger logs a line with method, path, status and ms duration', async () => {
  const logs = [];
  const originalLog = console.log;
  console.log = (...args) => { logs.push(args.join(' ')); };

  const app = express();
  app.use(requestLogger);
  app.get('/ping', (_req, res) => res.status(200).json({ ok: true }));

  const server = app.listen(0);
  await new Promise((resolve) => server.once('listening', resolve));
  const port = server.address().port;

  try {
    const res = await fetch(`http://localhost:${port}/ping`);
    await res.json();
    await new Promise((resolve) => setTimeout(resolve, 50));

    const line = logs.find((l) => l.includes('/ping'));
    assert.ok(line, 'expected a log line for /ping');
    assert.match(line, /GET/);
    assert.match(line, /\/ping/);
    assert.match(line, /200/);
    assert.match(line, /\d+(\.\d+)?ms/);
  } finally {
    console.log = originalLog;
    await new Promise((resolve) => server.close(resolve));
  }
});

