test("list: search, category filter, sort, pagination, active-only default", () => {
  const repo = new ProductsRepository();
  const service = new ProductsService(repo, sequentialIds("prod"));

  service.create({ name: "Blue Mug", description: "ceramic", priceCents: 500, stock: 10, category: "home" });
  service.create({ name: "Red Mug", description: "glass", priceCents: 300, stock: 10, category: "home" });
  service.create({ name: "Hammer", description: "steel tool", priceCents: 1200, stock: 10, category: "tools" });
  const inactive = service.create({ name: "Old Mug", description: "ceramic", priceCents: 100, stock: 10, category: "home" });
  service.update(inactive.id, { active: false });

  const base = { page: 1, pageSize: 20 };

  const byCategory = service.list({ ...base, sort: "price" }, false);
  const homeOnly = byCategory.items.filter((p) => p.category === "home");
  assert.equal(homeOnly.length, 2);
  assert.ok(!byCategory.items.some((p) => p.name === "Old Mug"));

  const searched = service.list({ ...base, q: "mug", sort: "-price" }, false);
  assert.deepEqual(searched.items.map((p) => p.name), ["Blue Mug", "Red Mug"]);

  const categoryFiltered = service.list({ ...base, category: "tools", sort: "name" }, false);
  assert.equal(categoryFiltered.items.length, 1);
  assert.equal(categoryFiltered.items[0].name, "Hammer");

  const page1 = service.list({ page: 1, pageSize: 2, sort: "name" }, false);
  assert.equal(page1.items.length, 2);
  assert.equal(page1.total, 3);
  assert.equal(page1.totalPages, 2);

  const withInactive = service.list({ ...base, sort: "name" }, true);
  assert.ok(withInactive.items.some((p) => p.name === "Old Mug"));
});

