test("reserveStock decrements stock, releaseStock increments, rejects insufficient/inactive stock", () => {
  const repo = new ProductsRepository();
  const service = new ProductsService(repo, sequentialIds("prod"));

  const p1 = service.create({ name: "Pen", description: "", priceCents: 100, stock: 5, category: "office" });
  const p2 = service.create({ name: "Book", description: "", priceCents: 200, stock: 2, category: "office" });

  service.reserveStock([
    { productId: p1.id, quantity: 2 },
    { productId: p2.id, quantity: 1 },
  ]);
  assert.equal(service.get(p1.id).stock, 3);
  assert.equal(service.get(p2.id).stock, 1);

  assert.throws(
    () => service.reserveStock([{ productId: p2.id, quantity: 10 }]),
    /not enough stock/i,
  );
  assert.equal(service.get(p2.id).stock, 1, "stock unchanged after failed reservation");

  service.update(p1.id, { active: false });
  assert.throws(
    () => service.reserveStock([{ productId: p1.id, quantity: 1 }]),
    /no longer available/i,
  );

  service.releaseStock([{ productId: p2.id, quantity: 1 }]);
  assert.equal(service.get(p2.id).stock, 2);
});

